export function LoanEstimate({values}:{values:Record<string,string>}){
 const principal=parseMoneyCents(values['Valor emprestado (R$)']||''),payment=parseMoneyCents(values['Valor de cada parcela (R$)']||''),count=Number(values['Quantidade de parcelas']);
 const valid=principal>0&&payment>0&&Number.isInteger(count)&&count>=1&&count<=120,total=payment*count;
 if(!valid||total<principal)return <View style={{padding:16,borderWidth:1,borderColor:C.line,borderRadius:12}}><Text style={u.small}>{valid?'O total das parcelas deve cobrir o valor emprestado.':'Informe o valor emprestado, a quantidade e o valor da parcela.'}</Text></View>;
 let lo=0,hi=payment/principal;for(let i=0;i<100;i++){const rate=(lo+hi)/2,pv=payment*(-Math.expm1(-count*Math.log1p(rate)))/rate;if(pv>principal)lo=rate;else hi=rate;}
 const rate=total===principal?0:(lo+hi)*50;
 return <View accessibilityLiveRegion="polite" style={{padding:16,gap:6,backgroundColor:C.soft,borderWidth:1,borderColor:C.line,borderRadius:12}}><Text style={{fontSize:12,color:C.muted}}>Total a receber</Text><Text style={{fontSize:26,fontWeight:'700',color:C.ink,letterSpacing:-.35}}>{money(total)}</Text><Text style={{fontSize:11,color:C.muted}}>{total===principal?'Sem juros':'Juros totais '+money(total-principal)+' · taxa equivalente '+rate.toLocaleString('pt-BR',{maximumFractionDigits:2})+'% a.m. (informativa)'}</Text></View>;
}
