export function categoryIcon(name:string){const normalized=name.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return /mercado|supermerc/.test(normalized)?'cart':/comida|aliment|restaur|delivery|cafe|acougue/.test(normalized)?'food':/casa|moradia|aluguel/.test(normalized)?'home':/emprest/.test(normalized)?'users':/taxa|salario|renda/.test(normalized)?'income':/cofr|reserva/.test(normalized)?'lock':/cartao/.test(normalized)?'card':'bag';}
